function createFilter(filter: WixDataFilterInput): Record<string, any> {
  if (filter == null) {
    return {}
  }
  const anyFilter = filter as any
  if (typeof anyFilter.getFilterModel === 'function') {
    try {
      const model = anyFilter.getFilterModel()
      if (model != null) {
        return model
      }
    } catch (_e) {
      // fall back below
    }
  }
  if (anyFilter.filterTree != null) {
    return anyFilter.filterTree as Record<string, any>
  }
  if (isObject(filter)) {
    return filter as Record<string, any>
  }
  return {}
}

function createExplicitFilter(filter: WixDataFilterInput): Record<string, any> {
  if (filter == null) {
    throw wdeValidationError(messages.filterMustBeAnObject())
  }

  const anyFilter = filter as any
  if (typeof anyFilter.getFilterModel === 'function') {
    return anyFilter.getFilterModel() ?? {}
  }
  if (anyFilter.filterTree != null) {
    return anyFilter.filterTree as Record<string, any>
  }
  if (isObject(filter)) {
    return filter as Record<string, any>
  }

  throw wdeValidationError(messages.filterMustBeAnObject())
}

type ProvidedOpt<T> = T | undefined | Provider<T | undefined>
type TraceWith = (
  label: string,
  opts?: object
) => <T>(fn: () => Promise<T>) => Promise<T>
