  async get<Item extends Record<string, any> = WixDataItem>(
    collectionName: string,
    itemId: string,
    options?: WixDataGetOptions
  ): Promise<(Item & WixDataItem) | null> {
    await apiValidator()
      .arity('get', arguments, 2, 3)
      .collectionName(collectionName)
      .itemId(itemId)
      .options(options)
      .validateAndReject()

    return this.trace('get', { collectionName, itemId })(async (env) => {
      const { dataItem } = await this.client
        .getDataItem({
          ...env,
          dataCollectionId: collectionName,
          dataItemId: itemId,
          ...toReadOptions(options),
          fields: options?.fields,
          includeReferences: options?.includeReferences,
          ...(options?.includeFieldGroups?.length
            ? { includeFieldGroups: options.includeFieldGroups }
            : {}),
        })
        .catch(
          recover(ItemDoesNotExistCode, {} as apiTypes.GetDataItemResponse)
        )

      return dataItem
        ? (toDataItem(dataItem) as unknown as Item & WixDataItem)
        : null
    })
  }

  async insert<Item extends Record<string, any>>(
    collectionName: string,
    item: Item,
    options?: WixDataUpdateOptions
  ): Promise<Item & WixDataItem> {
    const itemAsWixData = item as Partial<WixDataItem>
    await apiValidator()
      .arity('insert', arguments, 2, 3)
      .collectionName(collectionName)
      .item(itemAsWixData, collectionName, false)
      .options(options)
      .validateAndReject()

    warnAboutBrokenFields(itemAsWixData)

    return this.trace('insert', { collectionName })(async (env) => {
      const { dataItem } = await this.client.insertDataItem({
        ...env,
        dataCollectionId: collectionName,
        dataItem: {
          id: itemAsWixData._id,
          data: itemAsWixData,
        },
        ...toInsertOptions(options),
      })

      return toDataItem(dataItem!) as unknown as Item & WixDataItem
    })
  }

