  insertReference<
    ItemLeft extends WithId = WixDataItem,
    ItemRight extends WithId = WixDataItem
  >(
    collectionName: string,
    refs: WixDataReference<ItemLeft, ItemRight>[],
    options?: WixDataOptions
  ): Promise<void>
  insertReference<ItemLeft extends WithId, ItemRight extends WithId>(
    collectionName: string,
    relationshipAttribute: string,
    left: WixDataItemOrId<ItemLeft>,
    right: WixDataItemOrId<ItemRight> | WixDataItemOrId<ItemRight>[],
    options?: WixDataOptions
  ): Promise<void>
  async insertReference(
    collectionName: string,
    refsOrAttr: any,
    leftOrOpts?: any,
    right?: any,
    options?: any
  ): Promise<void> {
    let refs: WixDataReference[]
    let opts: WixDataOptions
    let argc: [number, number]

    if (typeof refsOrAttr === 'string') {
      const rights: WixDataItemOrId[] = asArray(right)
      refs = rights.map((r) => ({
        relationshipName: refsOrAttr,
        left: leftOrOpts as WixDataItemOrId,
        right: r,
      }))
      opts = options
      argc = [4, 5]
    } else {
      refs = refsOrAttr
      opts = leftOrOpts
      argc = [2, 3]
    }

    await apiValidator()
      .arity('insertReference', arguments, ...argc)
      .collectionName(collectionName)
      .references(refs)
      .options(opts)
      .validateAndReject()

    await this.trace('insertReference', { collectionName })(async (env) =>
      this.client.bulkInsertDataItemReferences({
        ...env,
        dataCollectionId: collectionName,
        dataItemReferences: refs.map((r) => ({
          referringItemFieldName: r.relationshipName,
          referringItemId: toItemId(r.left),
          referencedItemId: toItemId(r.right),
        })),
        ...toOptions(opts),
      })
    )
  }

